import { Textarea as TextareaPrimitive } from "@ui-sdk/react/textarea"
import type { ComponentProps } from "react"
import { withClass } from "@/lib/utils"
import { textareaStyles } from "./textarea.styles"

function Textarea({ className, ...props }: ComponentProps<typeof TextareaPrimitive>) {
  return (
    <TextareaPrimitive
      className={withClass(
        textareaStyles.root,
        className,
      )}
      {...props}
    />
  )
}

export { Textarea }

// Framework-free: plain class strings for each part, so any version of 13UI can share them.
export const textareaStyles = {
  root: "w-full min-w-0 resize-none bg-transparent text-sm text-foreground outline-none placeholder:text-subtle-foreground focus-visible:outline-none data-disabled:opacity-50",
}
